// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(address newOwner) public {
        // Full admissible domain: any address, including address(0), may be proposed.
        // This test contract is the owner (constructor assigns _msgSender()).
        vm.prank(address(this));
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: whenever the ownership transfer succeeds, the owner must
        // become exactly the proposed address AND that address must be nonzero —
        // ownership can never be transferred to address(0) via transferOwnership.
        assertTrue(!ok || (ok && newOwner != address(0) && c.owner() == newOwner));
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
